    plugins []int
}

func (pm *Manager) init() {
    var group sync.WaitGroup
    group.Add(len(pm.plugins))
    for _, p := range pm.plugins {
        go func(p int) {
            defer group.Done()
        }(p)
        group.Wait() // Block here
    }
}

func Moby25384() {
    pm := &Manager{
        plugins: []int{1, 2},
    }
    go pm.init()
}
The  wait group increments its counter
depending on the number of plugins held by the
plugin manager , then iterates over each plugin
and spawns a goroutine.
Each goroutine decrements the counter once it finishes
its task with the  method.
However,  erroneously invokes  inside
the loop body, instead of after it!
This will cause any goroutine running the  method
when the manager has more than one plugin to leak.(pprof) list init
